(function(){var s=document.createElement("style");s.setAttribute("data-chunk","STORY_ARC");s.textContent="\n  .sa-tabs { display: flex; gap: 6px; flex-wrap: wrap; margin-bottom: 14px; }\n  .sa-tab { min-height: 40px; padding: 0 16px; border-radius: 10px; border: 1px solid var(--edge-2); background: transparent;\n    color: var(--fg-60); font-family: inherit; font-size: 13px; font-weight: 600; cursor: pointer; }\n  .sa-tab.on { border-color: var(--mint); color: var(--fg); background: rgba(23,255,197,.10); }\n\n  .sa-tiles { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 10px; margin-bottom: 14px; }\n  .sa-tile { border: 1px solid var(--edge-2); border-radius: 14px; padding: 14px; background: var(--glass-1); }\n  .sa-tile b { display: block; font-size: 25px; font-weight: 800; line-height: 1.1; }\n  .sa-tile span { display: block; font-size: 11.5px; color: var(--fg-55); margin-top: 3px; }\n  .sa-tile i { display: block; font-style: normal; font-size: 11px; color: var(--fg-45); margin-top: 4px; }\n  .sa-tile--ok b { color: var(--mint, #17ffc5); }\n  .sa-tile--bad b { color: #ff6b6b; }\n  .sa-tile--warn b { color: var(--amber, #f7b86b); }\n\n  .sa-verdict { border-radius: 14px; padding: 14px 16px; font-size: 13.5px; line-height: 1.65; margin-bottom: 14px; border: 1px solid var(--edge-2); }\n  .sa-verdict.ok { border-color: rgba(23,255,197,.4); background: rgba(23,255,197,.08); }\n  .sa-verdict.bad { border-color: rgba(255,107,107,.45); background: rgba(255,107,107,.10); }\n  .sa-verdict.warn { border-color: rgba(247,184,107,.45); background: rgba(247,184,107,.09); }\n\n  .sa-group { margin-bottom: 16px; }\n  .sa-group__h { display: flex; align-items: center; gap: 8px; font-size: 12px; font-weight: 700; text-transform: uppercase;\n    letter-spacing: .06em; color: var(--fg-55); padding: 0 2px 8px; }\n  .sa-group__h i { margin-left: auto; font-style: normal; text-transform: none; letter-spacing: 0; color: var(--fg-45); }\n  .sa-list { border: 1px solid var(--edge-2); border-radius: 14px; overflow: hidden; background: var(--glass-1); }\n  .sa-row { display: flex; align-items: center; gap: 10px; padding: 11px 14px; border-bottom: 1px solid var(--edge-2); }\n  .sa-list .sa-row:last-child { border-bottom: none; }\n  .sa-row--bad { box-shadow: inset 3px 0 0 #ff6b6b; }\n  .sa-row--warn { box-shadow: inset 3px 0 0 var(--amber, #f7b86b); }\n  .sa-row--ok { box-shadow: inset 3px 0 0 var(--mint, #17ffc5); }\n  .sa-row__m { flex: 1; min-width: 0; }\n  .sa-row__n { font-size: 13.5px; font-weight: 600; overflow-wrap: anywhere; }\n  .sa-row__d { font-size: 11.5px; color: var(--fg-55); margin-top: 2px; overflow-wrap: anywhere; }\n  .sa-kind { font-family: var(--f-mono, monospace); font-size: 10px; color: var(--fg-45); border: 1px solid var(--edge-2);\n    border-radius: 999px; padding: 1px 7px; margin-left: 6px; }\n  .sa-tag { font-size: 10.5px; padding: 3px 9px; border-radius: 999px; border: 1px solid var(--edge-2); color: var(--fg-55); }\n  .sa-tag.ok { color: var(--mint, #17ffc5); border-color: rgba(23,255,197,.4); }\n  .sa-tag.bad { color: #ff6b6b; border-color: rgba(255,107,107,.45); }\n\n  .sa-dur { width: 92px; min-height: 40px; border-radius: 10px; border: 1px solid var(--edge-2);\n    background: var(--ink-2, rgba(0,0,0,.25)); color: var(--fg); font-family: var(--f-mono, monospace); font-size: 14px; padding: 0 10px; text-align: right; }\n  .sa-unit { font-size: 11px; color: var(--fg-45); }\n\n  .sa-fields { display: grid; grid-template-columns: repeat(auto-fit, minmax(190px, 1fr)); gap: 10px; margin-bottom: 14px; }\n  .sa-field { display: flex; flex-direction: column; gap: 5px; }\n  .sa-field span { font-size: 11.5px; color: var(--fg-55); }\n  .sa-field input { min-height: 44px; border-radius: 10px; border: 1px solid var(--edge-2);\n    background: var(--ink-2, rgba(0,0,0,.25)); color: var(--fg); font-family: inherit; font-size: 15px; padding: 0 12px; }\n\n  .sa-bar { height: 8px; border-radius: 5px; background: rgba(255,255,255,.09); overflow: hidden; margin: 4px 0 16px; }\n  .sa-bar span { display: block; height: 100%; background: linear-gradient(90deg, var(--mint, #17ffc5), var(--aqua, #14afdf)); }\n  .sa-share { flex: 0 0 90px; height: 6px; border-radius: 4px; background: rgba(255,255,255,.08); overflow: hidden; }\n  .sa-share span { display: block; height: 100%; background: var(--mint, #17ffc5); }\n  .sa-sel { min-height: 40px; border-radius: 10px; border: 1px solid var(--edge-2); background: var(--ink-2, rgba(0,0,0,.25)); color: var(--fg); font-family: inherit; font-size: 13px; padding: 0 10px; }\n  .sa-note { font-size: 12px; color: var(--fg-55); line-height: 1.6; border-left: 2px solid var(--edge-2); padding-left: 12px; margin: 12px 0; }\n  .sa-actions { display: flex; gap: 8px; flex-wrap: wrap; margin-top: 14px; }\n  .sa-empty { border: 1px dashed var(--edge-2); border-radius: 16px; padding: 34px 22px; text-align: center; }\n  .sa-empty__t { font-size: 17px; font-weight: 700; }\n  .sa-empty__d { font-size: 13.5px; color: var(--fg-60); line-height: 1.6; margin: 8px auto 16px; max-width: 480px; }\n  .sa-empty__a { display: flex; gap: 8px; justify-content: center; flex-wrap: wrap; }\n";document.head.appendChild(s);})();
